/// <summary>
/// desigend from AVA
/// </summary>
[ExtensionOf(formDataSourceStr(DocuView,DocuRef))]
internal final class AVADocuViewFrm_DocuRefDS_Extension
{

}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
void  write()
{
    next write();
    FormRun formRun = this.formRun();

    FormDataSource          docuRestrictionDS = formRun.dataSource('AVADocuRestrictionReference');
    FormDataSource          docuRefDS = formRun.dataSource('DocuRef');
    DocuRef                 locDocuref = docuRefDS.cursor();
    if (docuRefDS)
    {
        locDocuref = docuRefDS.cursor();
    }
    if (docuRestrictionDS)
    {
        AVADocuRestrictionReference     locDocuRestrictionReference;
        AVADocuRestrictionReference     curDocuRestrictionReference; 
        select firstonly locDocuRestrictionReference
            where locDocuRestrictionReference.DocuRefRecId == locDocuref.RecId;

        curDocuRestrictionReference = docuRestrictionDS.cursor();

        curDocuRestrictionReference.data(locDocuRestrictionReference);
    }
}
